function pitch(){let roles=D.formations[S.formation],coords=FORMATION_COORDS[S.formation]||FORMATION_COORDS['4-3-3'];return `<div class="pitch tacticalPitch">${S.xi.map((id,i)=>{let [x,y]=coords[i];return `<div class=fieldSlot style="left:${x}%;top:${y}%">${pcard(S.players[id],roles[i])}</div>`}).join('')}<div class=centerCircle></div><div class=halfLine></div></div>`}
function more(){stopTimer();ensureV4();layout('Mais',`<div class=grid><div class="card s6"><h3>Opções de partida</h3><label>Velocidade padrão<select class=chip onchange="S.speed=+this.value;save()">${[[1,'1×'],[2,'2×'],[4,'4×'],[99,'Instantâneo']].map(x=>`<option value=${x[0]} ${S.speed===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></label><p><label><input type=checkbox ${S.autoPause?'checked':''} onchange="S.autoPause=this.checked;save()"> Pausar em eventos críticos</label></p><button class=btn onclick=toggleTheme()>Alternar tema</button></div><div class="card s6"><h3>Áudio</h3><label>Volume <input type=range min=0 max=1 step=.05 value="${S.audioVolume}" onchange="S.audioVolume=+this.value;save()"></label><p><label><input type=checkbox ${S.audioMuted?'checked':''} onchange="S.audioMuted=this.checked;save();if(S.audioMuted)AudioFX.stopLoop()"> Mudo</label></p><button class="btn alt" onclick="AudioFX.play('apito_inicio')">TESTAR ÁUDIO</button></div><div class="card s6"><h3>Carreira</h3><p>Treinador: <b>${S.coach}</b><br>Seed: <b>${S.seed}</b><br>Versão do save: <b>${S.version}</b></p><div class=row><button class="btn alt" onclick=exportSave()>EXPORTAR SAVE</button><button class="btn alt" onclick=exportDiagnostic()>DIAGNÓSTICO</button></div></div><div class="card s6"><h3>Navegação</h3><p class=muted>Voltar ao menu não apaga nem encerra a carreira. Uma partida em andamento continuará disponível em “Continuar”.</p><button class=btn onclick=returnMainMenu()>VOLTAR AO MENU PRINCIPAL</button></div><div class="card s6"><h3>Mercado 🔒</h3><p class=muted>Janela encerrada. O desafio desta versão é trabalhar com o elenco disponível.</p></div><div class="card s6"><h3>Créditos</h3><p>Feito por <b>@felipelessa03</b></p><p><a href="https://github.com/feliperamoslessa" target="_blank" rel="noopener noreferrer">github.com/feliperamoslessa ↗</a></p></div></div>`)}
function exportDiagnostic(){let m=S.match||{};let d={gameVersion:13,career:S.career,round:S.round,seed:S.seed,formation:S.formation,position:pos(),points:team('Corinthians').pts,match:m?{round:m.round,minute:m.minute,display:m.display,phase:m.phase,done:m.done,paused:m.paused,score:[m.hg,m.ag],seed:m.seed}:null,savedAt:S.savedAt};let b=new Blob([JSON.stringify(d,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=`diagnostico-salve-corinthians-${S.seed}.json`;a.click();URL.revokeObjectURL(a.href)}
function matchView(){let m=S.match;if(!m){home();return}let virtual=virtualTable(),idx=virtual.findIndex(x=>x.name==='Corinthians');layout('Início',`<section class=matchTop><span class=season>R${m.round} • ${m.display}</span><div class=matchScore><span>${m.home}</span><strong>${m.hg} × ${m.ag}</strong><span>${m.away}</span></div><div class=row style="justify-content:center"><button class=chip onclick=cycleSpeed()>${S.speed===99?'INSTANT':S.speed+'×'}</button><select class=chip onchange="changeMentality(this.value)">${opts(['Defensiva','Equilibrada','Ofensiva'],S.mentality)}</select><button class=chip onclick="pauseMatch()" ${m.done?'disabled':''}>${m.paused?'▶':'Ⅱ'}</button></div></section><div class=grid><div class="card s7"><div class=rowBetween><div class=headline>Transmissão</div><span>${momentum()}</span></div><div class=events>${m.events.slice().reverse().map(e=>`<div class="event ${e.special?'special':''}">${e.text}</div>`).join('')||'<p class=muted>A bola está rolando...</p>'}</div></div><div class="card s5"><div class=headline>Ao vivo</div>${Object.values(m.live).filter(x=>!x.home.includes('Corinthians')&&!x.away.includes('Corinthians')).map(x=>`<div class=fixture><span>${x.home}</span><b>${x.hg}–${x.ag}</b><span>${x.away}</span></div>`).join('')}<div class=divider></div><div class=headline>Tabela virtual</div>${virtual.slice(Math.max(0,idx-2),Math.min(20,Math.max(0,idx-2)+6)).map(x=>`<div class="miniTable ${x.name==='Corinthians'?'focus':''} ${virtual.indexOf(x)>=16?'dangerRow':''}"><span>${virtual.indexOf(x)+1}</span><b>${x.name}</b><strong>${x.pts}</strong></div>`).join('')}</div><div class="card s12"><div class=statline><span>Finalizações <b>${m.stats.shotsH}–${m.stats.shotsA}</b></span><span>No alvo <b>${m.stats.onH}–${m.stats.onA}</b></span><span>Cartões <b>${m.stats.cardsH}–${m.stats.cardsA}</b></span><span>Trocas <b>${m.subs||0}/5</b></span></div><div class=row style="margin-top:12px"><button class="btn alt" onclick=openMatchSubs() ${m.done?'disabled':''}>GERENCIAR TIME</button></div></div></div>${m.paused&&m.ht?`<div class=modal><div class=card><span class=badge>INTERVALO</span><h2>${m.home} ${m.hg} × ${m.ag} ${m.away}</h2><p>Finalizações ${m.stats.shotsH}–${m.stats.shotsA}. Stamina média do XI: ${Math.round(S.xi.reduce((a,id)=>a+S.players[id].stamina,0)/11)}%.</p><button class=primaryBig onclick=continueSecond()>CONTINUAR 2º TEMPO</button></div></div>`:''}${m.done?`<div class=modal><div class="card fulltimeCard"><span class=badge>FIM DE JOGO</span><h2>${m.home} ${m.hg} × ${m.ag} ${m.away}</h2><p>O estado final foi salvo. Agora confira todos os resultados da rodada.</p><button class=primaryBig onclick=finishMatch()>VER RESULTADOS DA RODADA →</button></div></div>`:''}`)}
function openMatchSubs(){let m=S.match;if(!m||m.done)return;let was=!m.paused;m.paused=true;stopTimer();let xi=S.xi.map((id,i)=>`<option value=${i}>${S.players[id].name} • ${S.players[id].stamina}%</option>`).join(''),bench=S.bench.map(id=>`<option value=${id}>${S.players[id].name} • ${S.players[id].stamina}%</option>`).join('');app.insertAdjacentHTML('beforeend',`<div class=modal><div class=card><span class=badge>SUBSTITUIÇÃO</span><h2>Gerenciar time</h2><p>${m.subs||0}/5 substituições utilizadas.</p><label>Sai<select id=subOut class=chip>${xi}</select></label><label>Entra<select id=subIn class=chip>${bench}</select></label><div class=row style="margin-top:15px"><button class=btn onclick="confirmSub(${was})" ${(m.subs||0)>=5?'disabled':''}>CONFIRMAR TROCA</button><button class="btn alt" onclick="closeSub(${was})">VOLTAR</button></div></div></div>`)}
function closeSub(resume){document.querySelector('.modal')?.remove();if(resume){S.match.paused=false;save();startClock()}matchView()}
function confirmSub(resume){let m=S.match;if((m.subs||0)>=5)return;let slot=+document.getElementById('subOut').value,inId=+document.getElementById('subIn').value,outId=S.xi[slot],bi=S.bench.indexOf(inId);if(bi<0||outId===inId)return;S.xi[slot]=inId;S.bench[bi]=outId;m.subs=(m.subs||0)+1;m.events.push({text:`🔄 ${m.display} • ${S.players[inId].name} entra no lugar de ${S.players[outId].name}.`,special:true});AudioFX.play('substituicao',.7);save();closeSub(resume)}
const _oldKickoff=kickoff;kickoff=function(){_oldKickoff();ensureV4();if(S.match){S.match.state='FIRST_HALF';S.match.subWindows=0;AudioFX.play('apito_inicio');AudioFX.loop('torcida_ambiente');save()}};
const _oldContinueSecond=continueSecond;continueSecond=function(){AudioFX.play('apito_inicio',.7);if(S.match)S.match.state='SECOND_HALF';_oldContinueSecond()};
const _oldTick=tick;tick=function(){let before=S.match?S.match.done:false;_oldTick();let m=S.match;if(!m)return;let drain=(S.mentality==='Ofensiva'?.075:S.mentality==='Defensiva'?.045:.06)*(S.press==='Alta'?1.25:S.press==='Baixa'?.85:1)*(S.tempo==='Alto'?1.18:S.tempo==='Baixo'?.88:1);if(!m.done&&!m.paused)S.xi.forEach(id=>S.players[id].stamina=Math.max(25,+(S.players[id].stamina-drain).toFixed(2)));if(m.ht&&m.paused){m.state='HALF_TIME';AudioFX.play('apito_intervalo');save()}if(!before&&m.done){m.state='FULL_TIME';AudioFX.stopLoop();AudioFX.play('apito_fim');save()}};
const _oldFinish=finishMatch;finishMatch=function(){if(!S.match?.done)return;S.match.state='ROUND_RESULTS';_oldFinish()};
ensureV4();

/* ===== V5 match lock, match manager, stamina, archives and split feeds ===== */
let matchSubOut=null, matchSubIn=null;
function matchLocked(){return !!(S&&S.match)}
function nav(active){if(matchLocked())return '';return `<nav class=nav>${['Início','Elenco','Brasileirão','Notícias','Mais'].map(x=>`<button class="${active===x?'active':''}" onclick="go('${x}')">${x}</button>`).join('')}</nav>`}
function go(x){if(matchLocked()){matchView();return}({Início:home,Elenco:formation,Brasileirão:league,Notícias:news,Mais:more})[x]()}
function ensureV5(){if(!S)return;S.version=5;if(!S.archiveId)S.archiveId=`${S.seed}-${S.career||'career'}`;if(S.archived==null)S.archived=false;if(S.match){if(!S.match.otherEvents)S.match.otherEvents=[];if(!S.match.feed)S.match.feed='match';if(!S.match.staminaNoise)S.match.staminaNoise={};}save()}
function setMatchFeed(feed){if(!S.match)return;S.match.feed=feed;save();matchView()}
function matchOtherResults(m){let games=Object.values(m.live).filter(g=>g.home!=='Corinthians'&&g.away!=='Corinthians');return `<div class=otherScoreGrid>${games.map(g=>`<div class=otherScore><span>${g.home}</span><b>${g.hg}–${g.ag}</b><span>${g.away}</span></div>`).join('')}</div><div class=divider></div><div class=headline>Gols da rodada</div><div class="events otherFeed">${(m.otherEvents||[]).slice().reverse().map(e=>`<div class=event>${e.text}</div>`).join('')||'<p class=muted>Nenhum gol nos outros jogos até agora.</p>'}</div>`}
function matchView(){let m=S.match;if(!m){home();return}ensureV5();let virtual=virtualTable(),idx=virtual.findIndex(x=>x.name==='Corinthians'),feed=m.feed||'match';layout('Partida',`<section class=matchTop><span class=season>R${m.round} • ${m.display} • PARTIDA EM ANDAMENTO</span><div class=matchScore><span>${m.home}</span><strong>${m.hg} × ${m.ag}</strong><span>${m.away}</span></div><div class=row style="justify-content:center"><button class=chip onclick=cycleSpeed()>${S.speed===99?'INSTANT':S.speed+'×'}</button><select class=chip onchange="changeMentality(this.value)">${opts(['Defensiva','Equilibrada','Ofensiva'],S.mentality)}</select><button class=chip onclick="pauseMatch()" ${m.done?'disabled':''}>${m.paused?'▶':'Ⅱ'}</button></div><div class=matchLockNote>🔒 Durante a partida, a navegação do jogo fica bloqueada.</div></section>
<div class=grid><div class="card s7"><div class=matchFeedTabs><button class="${feed==='match'?'btn':'btn alt'}" onclick="setMatchFeed('match')">TRANSMISSÃO</button><button class="${feed==='others'?'btn':'btn alt'}" onclick="setMatchFeed('others')">OUTROS RESULTADOS</button></div>${feed==='match'?`<div class=rowBetween><div class=headline>Partida atual</div><span>${momentum()}</span></div><div class=events>${m.events.slice().reverse().map(e=>`<div class="event ${e.special?'special':''}">${e.text}</div>`).join('')||'<p class=muted>A bola está rolando...</p>'}</div>`:matchOtherResults(m)}</div>
<div class="card s5"><div class=headline>Tabela virtual</div>${virtual.slice(Math.max(0,idx-2),Math.min(20,Math.max(0,idx-2)+6)).map(x=>`<div class="miniTable ${x.name==='Corinthians'?'focus':''} ${virtual.indexOf(x)>=16?'dangerRow':''}"><span>${virtual.indexOf(x)+1}</span><b>${x.name}</b><strong>${x.pts}</strong></div>`).join('')}<div class=divider></div><small class=muted>Os gols dos outros jogos aparecem somente em “Outros resultados”.</small></div>
<div class="card s12"><div class=statline><span>Finalizações <b>${m.stats.shotsH}–${m.stats.shotsA}</b></span><span>No alvo <b>${m.stats.onH}–${m.stats.onA}</b></span><span>Cartões <b>${m.stats.cardsH}–${m.stats.cardsA}</b></span><span>Trocas <b>${m.subs||0}/5</b></span></div><div class=row style="margin-top:12px"><button class="btn alt" onclick=openMatchSubs() ${m.done?'disabled':''}>GERENCIAR TIME</button><button class="btn dangerBtn" onclick=askSimulate() ${m.done?'disabled':''}>SIMULAR PARTIDA</button></div></div></div>
${m.paused&&m.ht?`<div class=modal><div class=card><span class=badge>INTERVALO</span><h2>${m.home} ${m.hg} × ${m.ag} ${m.away}</h2><p>Finalizações ${m.stats.shotsH}–${m.stats.shotsA}. Stamina média do XI: ${Math.round(S.xi.reduce((a,id)=>a+S.players[id].stamina,0)/11)}%.</p><div class=row><button class="btn alt" onclick=openMatchSubs()>GERENCIAR TIME</button><button class=primaryBig onclick=continueSecond()>CONTINUAR 2º TEMPO</button></div></div></div>`:''}${m.done?`<div class=modal><div class="card fulltimeCard"><span class=badge>FIM DE JOGO</span><h2>${m.home} ${m.hg} × ${m.ag} ${m.away}</h2><p>O estado final foi salvo. Confira os resultados da rodada.</p><button class=primaryBig onclick=finishMatch()>VER RESULTADOS DA RODADA →</button></div></div>`:''}`)}
function askSimulate(){let m=S.match;if(!m||m.done)return;let wasPaused=m.paused;m.paused=true;stopTimer();save();app.insertAdjacentHTML('beforeend',`<div class=modal id=simModal><div class="card confirmCard"><span class=badge>SIMULAÇÃO</span><h2>Quer realmente simular a partida?</h2><p>A partida será processada até o fim usando a mesma seed, escalação, táticas e estado atual. Recarregar a página não muda o caminho já salvo.</p><div class=row><button class="btn alt" onclick="cancelSim(${wasPaused})">CANCELAR</button><button class="btn dangerBtn" onclick=simulateToEnd()>SIMULAR ATÉ O FIM</button></div></div></div>`)}
function cancelSim(wasPaused){document.getElementById('simModal')?.remove();if(S.match){S.match.paused=!!wasPaused;save();matchView();if(!S.match.paused)startClock()}}
function simulateToEnd(){document.getElementById('simModal')?.remove();let m=S.match;if(!m||m.done)return;stopTimer();m.paused=false;let guard=0;while(!m.done&&guard++<240){if(m.ht){m.phase='2H';m.minute=45;m.ht=false;m.paused=false;m.state='SECOND_HALF';m.events.push({text:'46′ • Começa o segundo tempo.',special:true})}tick();if(m.paused&&m.ht)continue;if(m.paused&&!m.done)m.paused=false}save();matchView()}
function staminaRoleFactor(p,role){if(role==='GOL'||p.pos==='GOL')return .28;if(['LD','LE','ALA-D','ALA-E'].includes(role))return 1.18;if(['PE','PD'].includes(role))return 1.14;if(['VOL','MC'].includes(role))return 1.05;if(role==='MEI')return 1.0;if(role==='CA')return .92;if(role==='ZAG')return .72;return 1}
function playerDrain(id,slot,m){let p=S.players[id],role=D.formations[S.formation][slot]||p.pos;if(m.staminaNoise[id]==null){let x=((m.seed^(id*1103515245))>>>0)%1000;m.staminaNoise[id]=.84+(x/1000)*.34}let tactical=(S.mentality==='Ofensiva'?1.1:S.mentality==='Defensiva'?.91:1)*(S.press==='Alta'?1.24:S.press==='Baixa'?.86:1)*(S.tempo==='Alto'?1.17:S.tempo==='Baixo'?.89:1);return .071*staminaRoleFactor(p,role)*m.staminaNoise[id]*tactical}
function tick(){let m=S.match;if(!m||m.paused||m.done)return;let wasDone=m.done;m.minute++;m.display=minuteLabel(m.minute,m.phase,m.st1,m.st2);simulateAllMinute();S.xi.forEach((id,i)=>{let p=S.players[id];p.stamina=Math.max(18,+(p.stamina-playerDrain(id,i,m)).toFixed(2))});if(m.phase==='1H'&&m.minute>=45+m.st1){m.ht=true;m.paused=true;m.state='HALF_TIME';m.events.push({text:`${m.display} • Intervalo.`,special:true});AudioFX.play('apito_intervalo');save();return}if(m.phase==='2H'&&m.minute>=90+m.st2){m.done=true;m.paused=true;m.state='FULL_TIME';m.events.push({text:`${m.display} • Fim de jogo.`,special:true});AudioFX.stopLoop();AudioFX.play('apito_fim');save();return}if(!wasDone)save()}
function corinthiansScorer(seed){
 let ids=S.xi.filter(id=>S.players[id]&&S.players[id].pos!=='GOL');
 let roleWeight={CA:8,PE:5.8,PD:5.8,MEI:4.5,MC:2.25,VOL:1.15,LD:.75,LE:.75,ZAG:.28,'ALA-D':2.1,'ALA-E':2.1};
 let weighted=ids.map(id=>{let p=S.players[id],role=playerRoleInXI(id)||p.pos,w=roleWeight[role]??roleWeight[p.pos]??1.5;w*=Math.max(.72,Math.min(1.22,(p.ovr||72)/76));w*=Math.max(.68,Math.min(1.05,(p.stamina||70)/82));return {id,w}});
 let total=weighted.reduce((a,x)=>a+x.w,0),r;[r,seed]=rng(seed);let target=r*total,chosen=weighted[weighted.length-1]?.id;
 for(let x of weighted){target-=x.w;if(target<=0){chosen=x.id;break}}
 return [chosen,seed]
}
function playerRoleInXI(id){let i=S.xi.indexOf(id),roles=D.formations[S.formation]||[];return i>=0?roles[i]:S.players[id]?.pos}
function simulateGameMinute(g,m){let r;[r,m.seed]=rng(m.seed);let isCor=g.home==='Corinthians'||g.away==='Corinthians',H=team(g.home),A=team(g.away),diff=(H.ovr-A.ovr)/18+.08;if(isCor){let corHome=g.home==='Corinthians',cs=xiStrength(),opp=team(corHome?g.away:g.home),bias=(cs-opp.ovr)/22+(S.mentality==='Ofensiva'?.07:S.mentality==='Defensiva'?-.05:0)+(corHome?.06:-.03);if(r<.180){let corChance;[r,m.seed]=rng(m.seed);corChance=r<.5+bias;if(corChance){corHome?m.stats.shotsH++:m.stats.shotsA++}else{corHome?m.stats.shotsA++:m.stats.shotsH++}[r,m.seed]=rng(m.seed);let goal=r<(corChance?.39:.37);if(goal){let club=corChance?'Corinthians':(corHome?g.away:g.home),sc;if(club==='Corinthians'){let scorerId;[scorerId,m.seed]=corinthiansScorer(m.seed);sc=S.players[scorerId].name;S.players[scorerId].goals++;addScorer(sc,'Corinthians');AudioFX.play('gol_corinthians')}else{[sc,m.seed]=scorerFor(club,m.seed);addScorer(sc,club);AudioFX.play('gol_adversario')}if(club===g.home)g.hg++;else g.ag++;m.events.push({text:`⚽ ${m.display} • ${sc} marca para ${club}!`,special:true});if(club===g.home)m.stats.onH++;else m.stats.onA++}else m.events.push({text:`${m.display} • ${corChance?'Corinthians':'Adversário'} cria uma boa chance, mas não marca.`})}else if(r<.194){m.events.push({text:`🟨 ${m.display} • Cartão amarelo.`});m.stats.cardsH++}}else if(r<.170){let homeChance;[r,m.seed]=rng(m.seed);homeChance=r<.5+diff;[r,m.seed]=rng(m.seed);if(r<.37){let club=homeChance?g.home:g.away,sc;[sc,m.seed]=scorerFor(club,m.seed);homeChance?g.hg++:g.ag++;addScorer(sc,club);g.events.push({minute:m.minute,scorer:sc,club});if(!m.otherEvents)m.otherEvents=[];m.otherEvents.push({text:`⚽ ${m.display} • ${g.home} ${g.hg}–${g.ag} ${g.away} • ${sc}`});if(relevantClub(club))AudioFX.play('notificacao_gol',.45)}}}
function matchManagerPitch(){let roles=D.formations[S.formation],coords=FORMATION_COORDS[S.formation]||FORMATION_COORDS['4-3-3'];return `<div class="pitch tacticalPitch matchManagerPitch">${S.xi.map((id,i)=>{let p=S.players[id],[x,y]=coords[i],sel=matchSubOut===i?'selected':'';return `<button class="fieldSlot matchPlayer ${sel}" style="left:${x}%;top:${y}%" onclick="selectMatchOut(${i})"><span class=pball>${eff(p,roles[i])}</span><b>${p.name.split(' ').slice(-1)}</b><small>${roles[i]} • ${Math.round(p.stamina)}%</small></button>`}).join('')}<div class=centerCircle></div><div class=halfLine></div></div>`}
function openMatchSubs(){let m=S.match;if(!m||m.done)return;m.managerResume=!m.paused;m.paused=true;stopTimer();matchSubOut=null;matchSubIn=null;save();renderMatchManager()}
function renderMatchManager(){let m=S.match;if(!m)return;let roles=D.formations[S.formation];app.innerHTML=`<main class="shell matchManagerShell"><header class=topbar><div><div class=brand>GERENCIAR TIME</div><div class=roundtag>${m.home} ${m.hg} × ${m.ag} ${m.away} • ${m.display}</div></div><span class=badge>${m.subs||0}/5 TROCAS</span></header><div class=rowBetween><div><div class=eyebrow>FORMAÇÃO ATUAL</div><h2>${S.formation}</h2></div><select class=chip onchange="changeMatchFormation(this.value)">${Object.keys(D.formations).map(f=>`<option ${f===S.formation?'selected':''}>${f}</option>`).join('')}</select></div><div class=grid><div class="card s7">${matchManagerPitch()}</div><div class="card s5"><div class=headline>Banco</div><p class=muted>Escolha um titular no campo e depois um jogador do banco.</p><div class=matchBench>${S.bench.map(id=>{let p=S.players[id];return `<button class="squadrow ${matchSubIn===id?'selectedRow':''}" onclick="selectMatchIn(${id})"><span class=miniovr>${p.ovr}</span><span><b>${p.name}</b><small>${p.pos} • ${Math.round(p.stamina)}%</small></span></button>`}).join('')}</div><div class=divider></div><div id=subPreview>${subPreviewHTML()}</div></div></div><div class="stickyActions"><button class="btn alt" onclick=cancelMatchManager()>VOLTAR À PARTIDA</button><button class=primaryBig onclick=confirmMatchManagerSub() ${(m.subs||0)>=5?'disabled':''}>CONFIRMAR ALTERAÇÃO</button></div></main>`}
function selectMatchOut(i){matchSubOut=i;renderMatchManager()}
function selectMatchIn(id){matchSubIn=id;renderMatchManager()}
function subPreviewHTML(){if(matchSubOut==null||matchSubIn==null)return '<p class=muted>Nenhuma alteração selecionada.</p>';let o=S.players[S.xi[matchSubOut]],n=S.players[matchSubIn],role=D.formations[S.formation][matchSubOut];return `<div class=subPreview><b>${o.name} ↓</b><span>→</span><b>${n.name} ↑</b><small>${Math.round(o.stamina)}% → ${Math.round(n.stamina)}% • OVR efetivo ${eff(n,role)}</small></div>`}
function changeMatchFormation(v){S.formation=v;save();renderMatchManager()}
function cancelMatchManager(){let resume=S.match?.managerResume;if(S.match){S.match.paused=!resume;delete S.match.managerResume;save()}matchSubOut=matchSubIn=null;matchView();if(resume)startClock()}
function confirmMatchManagerSub(){let m=S.match;if(!m||matchSubOut==null||matchSubIn==null||(m.subs||0)>=5)return;let outId=S.xi[matchSubOut],bi=S.bench.indexOf(matchSubIn);if(bi<0)return;let inId=matchSubIn;S.xi[matchSubOut]=inId;S.bench[bi]=outId;m.subs=(m.subs||0)+1;m.events.push({text:`🔄 ${m.display} • ${S.players[inId].name} entra no lugar de ${S.players[outId].name}.`,special:true});AudioFX.play('substituicao',.7);matchSubOut=matchSubIn=null;save();renderMatchManager()}
function careerArchiveSnapshot(){sortTable();let x=finalStats(),c=team('Corinthians');return {id:S.archiveId,name:S.career,coach:S.coach,seed:S.seed,version:S.version,date:new Date().toLocaleDateString('pt-BR'),reason:S.reason,pos:pos(),pts:c.pts,record:{w:x.w,d:x.d,l:x.l,gf:x.gf,ga:x.ga},table:clone(S.table),scorers:clone(S.scorers).sort((a,b)=>b.goals-a.goals),players:clone(S.players),history:clone(S.history),timeline:clone(S.timeline),results:clone(S.results),formation:S.formation}}
function archiveCareer(){ensureV5();let a=JSON.parse(localStorage.getItem(ARCH)||'[]');if(S.archived||a.some(x=>x.id===S.archiveId)){S.archived=true;save();alert('Esta carreira já foi salva no Hall.');return}a.push(careerArchiveSnapshot());localStorage.setItem(ARCH,JSON.stringify(a));S.archived=true;save();alert('Carreira salva no Hall. Você pode abrir o resumo completo pelo menu principal.')}
function archives(){stopTimer();let a=JSON.parse(localStorage.getItem(ARCH)||'[]');document.body.className=S?.theme==='light'?'light':'';app.innerHTML=`<main class=shell><div class=rowBetween><div><div class=eyebrow>ARQUIVO</div><h1>Hall de carreiras</h1></div><button class="btn alt" onclick=menu()>MENU PRINCIPAL</button></div>${a.length?`<div class=archiveGrid>${a.map((x,i)=>`<article class=archiveCard><span class=badge>${x.reason||'Carreira finalizada'}</span><div class=archivePos>${x.pos}º</div><h3>${x.name}</h3><p>${x.pts} pontos • ${x.record?`${x.record.w}V ${x.record.d}E ${x.record.l}D`:''}</p><small>${x.coach||''} • seed ${x.seed||'—'} • ${x.date||''}</small><button class=btn onclick="archiveDetail(${i})">VER CARREIRA →</button></article>`).join('')}</div>`:'<div class=card>Nenhuma carreira salva.</div>'}</main>`}
function archiveDetail(i,tab='resumo'){let a=JSON.parse(localStorage.getItem(ARCH)||'[]'),x=a[i];if(!x)return archives();let tabs=['resumo','tabela','artilharia','jogos','timeline'];let body='';if(tab==='tabela')body=`<div class=card>${(x.table||[]).map((t,j)=>`<div class="miniTable ${t.name==='Corinthians'?'focus':''} ${j>=16?'dangerRow':''}"><span>${j+1}</span><b>${t.name}</b><strong>${t.pts}</strong></div>`).join('')}</div>`;else if(tab==='artilharia')body=`<div class=grid><div class="card s6"><div class=headline>Artilharia geral</div>${(x.scorers||[]).slice(0,20).map((p,j)=>`<div class=fixture><span>${j+1}. ${p.name}<small> ${p.club}</small></span><b>${p.goals}</b><span>gols</span></div>`).join('')}</div><div class="card s6"><div class=headline>Corinthians</div>${(x.players||[]).slice().sort((a,b)=>(b.goals||0)-(a.goals||0)).slice(0,12).map((p,j)=>`<div class=fixture><span>${j+1}. ${p.name}</span><b>${p.goals||0}</b><span>gols</span></div>`).join('')}</div></div>`;else if(tab==='jogos')body=`<div class=card>${(x.history||[]).map(h=>`<div class=fixture><span>R${h.round} • ${h.opp}</span><b>${h.gf} × ${h.ga}</b><span>${h.res}</span></div>`).join('')}</div>`;else if(tab==='timeline')body=`<div class=card>${(x.timeline||[]).map(t=>`<div class=timeline><b>R${t.round}</b><span><strong>${t.title}</strong><small>${t.body}</small></span></div>`).join('')}</div>`;else body=`<div class=archiveHero><span class=season>${x.reason}</span><div class=archivePos>${x.pos}º</div><h2>${x.name}</h2><p>${x.pts} pontos • ${x.record?`${x.record.w}V ${x.record.d}E ${x.record.l}D • ${x.record.gf} GP • ${x.record.ga} GC`:''}</p><small>${x.coach} • seed ${x.seed} • dados V${x.version||'—'}</small></div>`;document.body.className=S?.theme==='light'?'light':'';app.innerHTML=`<main class=shell><div class=rowBetween><button class="btn alt" onclick=archives()>← HALL</button><b>${x.name}</b></div><div class=archiveTabs>${tabs.map(t=>`<button class="${tab===t?'btn':'btn alt'}" onclick="archiveDetail(${i},'${t}')">${t.toUpperCase()}</button>`).join('')}</div>${body}</main>`}
function finalScreen(){stopTimer();ensureV5();sortTable();let c=team('Corinthians'),p=pos(),x=finalStats(),ok=p<=16&&!String(S.reason).startsWith('Demitido');layout('',`<section class="finalHero finalHeroV5"><span class=season>${S.reason}</span><div class=finalResult>${ok?'MISSÃO CUMPRIDA':'FIM DA MISSÃO'}</div><div class=finalPos>${p}º</div><h1>${ok?'CORINTHIANS PERMANECE NA SÉRIE A':'A TEMPORADA TERMINOU'}</h1><p>${S.startPos}º → ${p}º • ${S.startPts} → ${c.pts} pontos</p><div class=finalRecord>${x.w}V <i>•</i> ${x.d}E <i>•</i> ${x.l}D <i>•</i> ${x.gf}–${x.ga} gols</div></section><div class=grid><div class="card s4 metric"><span>ARTILHEIRO DO CLUBE</span><b>${x.top?.name||'—'}</b><small>${x.top?.goals||0} gols</small></div><div class="card s4 metric"><span>MELHOR SEQUÊNCIA</span><b>${Math.max(0,S.bestStreak)}V</b></div><div class="card s4 metric"><span>FORMAÇÃO FINAL</span><b>${S.formation}</b></div><div class="card s6"><div class=headline>A sua história</div>${S.timeline.slice(-8).map(t=>`<div class=timeline><b>R${t.round}</b><span><strong>${t.title}</strong><small>${t.body}</small></span></div>`).join('')}</div><div class="card s6"><div class=headline>Classificação final</div>${S.table.slice(Math.max(0,p-4),Math.min(20,p+3)).map((t,j)=>`<div class="miniTable ${t.name==='Corinthians'?'focus':''}"><span>${S.table.indexOf(t)+1}</span><b>${t.name}</b><strong>${t.pts}</strong></div>`).join('')}<button class=btn style="margin-top:14px" onclick=sharePreview()>CRIAR CARD DA CARREIRA</button></div></div><div class="finalActions"><button class=primaryBig onclick=archiveCareer()>${S.archived?'✓ SALVA NO HALL':'SALVAR NO HALL'}</button><button class=ghostBig onclick=returnMainMenu()>VOLTAR AO MENU PRINCIPAL</button><button class="btn alt" onclick=newCareer()>JOGAR NOVAMENTE</button></div>`)}
