function sharePreview(){let c=team('Corinthians'),x=finalStats(),ok=pos()<=16&&!String(S.reason).startsWith('Demitido');app.insertAdjacentHTML('beforeend',`<div class=modal><div class="shareCard card shareCardV5"><span class=season>SALVE O CORINTHIANS • 2026</span><div class=posterStatus>${ok?'MISSÃO CUMPRIDA':'FIM DA MISSÃO'}</div><div class=finalPos>${pos()}º</div><h2>${c.pts} PONTOS</h2><div class=posterRecord>${x.w}V • ${x.d}E • ${x.l}D</div><p>${x.gf} gols marcados • ${x.ga} sofridos</p><div class=posterLine></div><b>${S.coach}</b><small>@felipelessa03 • seed ${S.seed}</small><div class=row style="justify-content:center;margin-top:18px"><button class=btn onclick=downloadCard()>BAIXAR PNG</button><button class="btn alt" onclick="this.closest('.modal').remove()">FECHAR</button></div></div></div>`)}
function downloadCard(){let c=document.createElement('canvas');c.width=1080;c.height=1350;let g=c.getContext('2d'),t=team('Corinthians'),x=finalStats(),ok=pos()<=16&&!String(S.reason).startsWith('Demitido');let grad=g.createLinearGradient(0,0,1080,1350);grad.addColorStop(0,'#08090b');grad.addColorStop(.55,'#17191d');grad.addColorStop(1,'#050506');g.fillStyle=grad;g.fillRect(0,0,1080,1350);g.strokeStyle='#34373d';g.lineWidth=2;g.strokeRect(55,55,970,1240);g.fillStyle='#9da3ae';g.font='700 28px Arial';g.fillText('SALVE O CORINTHIANS • 2026',90,120);g.fillStyle='#fff';g.font='900 48px Arial';g.fillText(ok?'MISSÃO CUMPRIDA':'FIM DA MISSÃO',90,220);g.font='900 300px Arial';g.fillText(`${pos()}º`,75,555);g.font='900 82px Arial';g.fillText(`${t.pts} PONTOS`,90,690);g.font='800 48px Arial';g.fillText(`${x.w}V   •   ${x.d}E   •   ${x.l}D`,90,790);g.fillStyle='#b9bdc5';g.font='500 34px Arial';g.fillText(`${x.gf} gols marcados  •  ${x.ga} sofridos`,90,860);g.strokeStyle='#34373d';g.beginPath();g.moveTo(90,930);g.lineTo(990,930);g.stroke();g.fillStyle='#fff';g.font='800 38px Arial';g.fillText(S.coach,90,1040);g.fillStyle='#9da3ae';g.font='500 28px Arial';g.fillText(`@felipelessa03  •  seed ${S.seed}`,90,1090);g.font='600 25px Arial';g.fillText('github.com/feliperamoslessa',90,1215);let a=document.createElement('a');a.download=`salve-o-corinthians-${S.seed}.png`;a.href=c.toDataURL('image/png');a.click()}
