/* ===== V6 polish, security-minded UI, richer match flow ===== */
function safeText(v,max=60){return String(v??'').replace(/[<>"'`]/g,'').replace(/[\u0000-\u001F]/g,' ').trim().slice(0,max)||'—'}
function ensureV6(){if(!S)return;S.version=13;S.coach=safeText(S.coach,40);S.career=safeText(S.career,50);if(S.audioVolume==null)S.audioVolume=.75;if(S.audioMuted==null)S.audioMuted=false;if(S.audioCrowd==null)S.audioCrowd=.65;if(S.audioEffects==null)S.audioEffects=.85;if(S.match){S.match.state=S.match.state||(S.match.done?'FULL_TIME':S.match.ht?'HALF_TIME':S.match.phase==='2H'?'SECOND_HALF':'FIRST_HALF');S.match.otherEvents=S.match.otherEvents||[];S.match.feed=S.match.feed||'match';S.match.staminaNoise=S.match.staminaNoise||{};S.match.eventLedger=S.match.eventLedger||[];S.match.processed=!!S.match.processed;}save()}
function newCareer(){if(S&&!S.finished&&!confirm('Iniciar nova carreira e substituir a carreira ativa?'))return;let n=safeText(prompt('Nome do treinador:','Felipe')||'Treinador',40),c=safeText(prompt('Nome da carreira:','Operação Permanência')||'Operação Permanência',50);S=fresh();S.version=13;S.coach=n;S.career=c;S.audioVolume=.75;S.audioCrowd=.65;S.audioEffects=.85;S.audioMuted=false;save();home()}
const _v6AudioPlay=AudioFX.play.bind(AudioFX),_v6AudioLoop=AudioFX.loop.bind(AudioFX);
AudioFX.play=function(name,vol=1){if(!S||S.audioMuted)return;let crowd=['torcida_comemoracao','torcida_vaia','torcida_pressao','gol_adversario'].includes(name);return _v6AudioPlay(name,vol*(crowd?(S.audioCrowd??.65):(S.audioEffects??.85)))};
AudioFX.loop=function(name){if(!S||S.audioMuted)return;this.stopLoop();try{let a=this.cache[name]||(this.cache[name]=new Audio(`assets/audio/${name}.mp3`));a.loop=true;a.volume=Math.min(1,(S.audioVolume??.75)*(S.audioCrowd??.65)*.45);let p=a.play();if(p&&p.catch)p.catch(()=>{});this.ambient=a}catch(e){}};
function setAudio(k,v){S[k]=+v;save();if(k==='audioCrowd'&&AudioFX.ambient)AudioFX.ambient.volume=Math.min(1,S.audioVolume*S.audioCrowd*.45)}
function more(){stopTimer();ensureV6();layout('Mais',`<div class=grid><div class="card s6"><h3>Opções de partida</h3><label>Velocidade padrão<select class=chip onchange="S.speed=+this.value;save()">${[[1,'1×'],[2,'2×'],[4,'4×'],[99,'Instantâneo']].map(x=>`<option value=${x[0]} ${S.speed===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></label><p><label><input type=checkbox ${S.autoPause?'checked':''} onchange="S.autoPause=this.checked;save()"> Pausar em eventos críticos</label></p><button class=btn onclick=toggleTheme()>Alternar tema</button></div><div class="card s6"><h3>Áudio</h3><label>Volume geral <input type=range min=0 max=1 step=.05 value="${S.audioVolume}" onchange="setAudio('audioVolume',this.value)"></label><label>Torcida <input type=range min=0 max=1 step=.05 value="${S.audioCrowd}" onchange="setAudio('audioCrowd',this.value)"></label><label>Efeitos <input type=range min=0 max=1 step=.05 value="${S.audioEffects}" onchange="setAudio('audioEffects',this.value)"></label><p><label><input type=checkbox ${S.audioMuted?'checked':''} onchange="S.audioMuted=this.checked;save();if(S.audioMuted)AudioFX.stopLoop()"> Silenciar áudio</label></p><div class=row><button class="btn alt" onclick="AudioFX.play('apito_inicio')">TESTAR APITO</button><button class="btn alt" onclick="AudioFX.play('torcida_comemoracao')">TESTAR TORCIDA</button></div></div><div class="card s6"><h3>Carreira</h3><p>Treinador: <b>${safeText(S.coach)}</b><br>Seed: <b>${S.seed}</b><br>Versão do save: <b>V${S.version}</b></p><div class=row><button class="btn alt" onclick=exportSave()>EXPORTAR SAVE</button><button class="btn alt" onclick=exportDiagnostic()>DIAGNÓSTICO</button></div></div><div class="card s6"><h3>Navegação</h3><p class=muted>Voltar ao menu não apaga a carreira. Se existir uma partida ativa, “Continuar” retorna exatamente a ela.</p><button class=btn onclick=returnMainMenu()>VOLTAR AO MENU PRINCIPAL</button></div><div class="card s6"><h3>Segurança e integridade</h3><p class=muted>O jogo não usa credenciais privadas no navegador. Saves têm validações de estado e ações críticas são protegidas contra execução duplicada.</p><button class="btn alt" onclick=exportDiagnostic()>EXPORTAR DIAGNÓSTICO</button></div><div class="card s6"><h3>Créditos</h3><p>Feito por <b>@felipelessa03</b></p><p><a href="https://github.com/feliperamoslessa" target="_blank" rel="noopener noreferrer">GitHub • feliperamoslessa ↗</a></p></div></div>`)}
function opponentSnapshot(){let f=fixture(),opp=f[0]==='Corinthians'?f[1]:f[0],t=team(opp),form=(S.results?Object.keys(S.results).sort((a,b)=>b-a).slice(0,5).map(r=>{let g=S.results[r]?.find(x=>x.home===opp||x.away===opp);if(!g)return null;let gf=g.home===opp?g.hg:g.ag,ga=g.home===opp?g.ag:g.hg;return gf>ga?'V':gf===ga?'E':'D'}).filter(Boolean):[]);return {name:opp,t,form:form.length?form.join(' '):'—'}}
function pregame(){ensureV6();let f=fixture(),e=S.pregame?.events[S.pregame.idx],o=opponentSnapshot(),avg=Math.round(S.xi.reduce((a,id)=>a+S.players[id].stamina,0)/11),roles=D.formations[S.formation];layout('Início',`<section class="dashboardHero pregameHero"><div><span class=season>PRÉ-JOGO • R${S.round} • ${D.dates[S.round]}</span><h1>${f[0]}<br>× ${f[1]}</h1><p>${f[0]==='Corinthians'?'Casa':'Fora de casa'} • missão: permanecer na Série A</p></div><aside><small>SUA EQUIPE</small><b>${S.formation}</b><span>${S.mentality} • condição média ${avg}%</span></aside></section><div class=grid><div class="card s7"><div class=eyebrow>ESCALAÇÃO</div><div class=headline>Corinthians</div>${pitch()}<div class=statline><span>Formação <b>${S.formation}</b></span><span>Pressão <b>${S.press}</b></span><span>Ritmo <b>${S.tempo}</b></span></div></div><div class="card s5"><div class=eyebrow>RELATÓRIO DO ADVERSÁRIO</div><div class=headline>${o.name}</div><div class=kpi>${S.table.indexOf(o.t)+1}º • ${o.t.pts} pts</div><p>OVR coletivo: <b>${o.t.ovr}</b><br>Forma recente: <b>${o.form}</b></p><div class=divider></div><p class=muted>Seu plano pode ser alterado até o apito inicial.</p><button class="btn alt" onclick=formation()>EDITAR ESCALAÇÃO</button></div>${e?`<div class="card s12"><div class=headline>${e.title}</div><p class=muted>${e.body}</p><div class=row><button class=btn onclick="decision('a')">${e.type==='talk'?'MOTIVAR':'PROMETER OPORTUNIDADE'}</button><button class="btn alt" onclick="decision('b')">${e.type==='talk'?'TIRAR A PRESSÃO':'SER DIRETO'}</button></div></div>`:`<div class="card s12 pregameLaunch"><div><div class=eyebrow>TUDO PRONTO</div><h2>Onze definidos. Plano definido.</h2><p class=muted>Ao entrar em campo, a navegação da carreira fica bloqueada até o fim da partida.</p></div><button class=primaryBig onclick=kickoff()>ENTRAR EM CAMPO →</button></div>`}</div>`)}
function staminaBand(v){return v>=76?'Boa':v>=56?'Normal':v>=36?'Cansado':v>=21?'Muito cansado':'Esgotado'}
function ledger(type,data={}){if(!S?.match)return;S.match.eventLedger=S.match.eventLedger||[];S.match.eventLedger.push({seq:S.match.eventLedger.length+1,minute:S.match.display,type,...data})}
