/* ===== V13 HIGH-SCORING calibration =====
   Goal-first hazard model calibrated for a more attacking Brasileirão.
   Target: intentionally high-scoring football: roughly 4.8-5.4 total goals per match over large samples, while
   preserving scoreless matches, strength, home advantage and deterministic RNG.
*/
function simulateGameMinute(g,m){
  let r; [r,m.seed]=rng(m.seed);
  const isCor=g.home==='Corinthians'||g.away==='Corinthians';
  const H=team(g.home), A=team(g.away);
  const minute=m.minute||1;
  const totalGoals=g.hg+g.ag;
  let goalHazard=.052;
  if(minute>=55 && totalGoals===0) goalHazard+=.010;
  if(minute>=70 && g.hg===g.ag) goalHazard+=.006;
  if(minute>=80 && Math.abs(g.hg-g.ag)===1) goalHazard+=.005;

  if(isCor){
    const corHome=g.home==='Corinthians';
    const cs=xiStrength(), opp=team(corHome?g.away:g.home);
    const mentality=S.mentality==='Ofensiva'?.055:S.mentality==='Defensiva'?-.035:0;
    let corShare=.50+(cs-opp.ovr)/70+mentality+(corHome?.035:-.02);
    corShare=Math.max(.30,Math.min(.70,corShare));

    // Visible attacking sequences are more frequent than goals.
    if(r<goalHazard){
      [r,m.seed]=rng(m.seed);
      const corGoal=r<corShare;
      const club=corGoal?'Corinthians':(corHome?g.away:g.home);
      let sc;
      if(club==='Corinthians'){
        let scorerId; [scorerId,m.seed]=corinthiansScorer(m.seed);
        sc=S.players[scorerId].name; S.players[scorerId].goals++; addScorer(sc,'Corinthians');
      }else{
        [sc,m.seed]=scorerFor(club,m.seed); addScorer(sc,club);
      }
      if(club===g.home){g.hg++;m.stats.shotsH++;m.stats.onH++}else{g.ag++;m.stats.shotsA++;m.stats.onA++}
      m.events.push({text:`⚽ ${m.display} • ${sc} marca para ${club}!`,special:true});
      ledger('goal',{club,scorer:sc,score:[g.hg,g.ag]});
      if(club==='Corinthians'){AudioFX.play('gol_corinthians');AudioFX.play('torcida_comemoracao',.85)}else AudioFX.play('gol_adversario');
      return;
    }

    // Non-goal chances keep the match active without inflating the score.
    if(r<goalHazard+.105){
      [r,m.seed]=rng(m.seed); const corChance=r<corShare;
      if(corChance){corHome?m.stats.shotsH++:m.stats.shotsA++}else{corHome?m.stats.shotsA++:m.stats.shotsH++}
      [r,m.seed]=rng(m.seed);
      if(r<.36){if((corChance&&corHome)||(!corChance&&!corHome))m.stats.onH++;else m.stats.onA++}
      m.events.push({text:`${m.display} • ${corChance?'Corinthians':'Adversário'} cria uma boa chance, mas não marca.`});
      return;
    }
    if(r<goalHazard+.119){m.events.push({text:`🟨 ${m.display} • Cartão amarelo.`});return}
    return;
  }

  // Other nine matches: direct calibrated goal hazard, with club strength deciding scorer side.
  if(r<goalHazard){
    let homeShare=.53+(H.ovr-A.ovr)/85;
    if(minute>=72){
      if(g.hg<g.ag)homeShare+=.035;
      if(g.ag<g.hg)homeShare-=.035;
    }
    homeShare=Math.max(.31,Math.min(.72,homeShare));
    [r,m.seed]=rng(m.seed); const homeGoal=r<homeShare;
    const club=homeGoal?g.home:g.away; let sc;
    [sc,m.seed]=scorerFor(club,m.seed);
    if(homeGoal)g.hg++;else g.ag++;
    addScorer(sc,club);
    g.events.push({minute:m.minute,scorer:sc,club});
    m.otherEvents=m.otherEvents||[];
    m.otherEvents.push({text:`⚽ ${m.display} • ${g.home} ${g.hg}–${g.ag} ${g.away} • ${sc}`});
  }
}

/* ===== V13 GUARANTEED HIGH-SCORING ENGINE =====
   Explicit goal schedule per fixture. This bypasses the legacy per-minute hazard path,
   so a low-scoring round can no longer happen because of a probability/override bug.
*/
function v13Rand(m){let r;[r,m.seed]=rng(m.seed);return r}
function v13GoalCount(m){
  const r=v13Rand(m);
  // Per-team goals: mostly 1-3, occasionally 0 or 4. Mean ~2.25/team (~4.5/game).
  if(r<.06)return 0;
  if(r<.31)return 1;
  if(r<.68)return 2;
  if(r<.91)return 3;
  return 4;
}
function v13BuildSchedule(g,m){
  if(g.goalSchedule)return;
  let hg=v13GoalCount(m), ag=v13GoalCount(m);
  // Keep scorelines varied and give team strength/home edge a small deterministic influence.
  const H=team(g.home),A=team(g.away),edge=(H.ovr-A.ovr)+(g.home==='Corinthians'?xiStrength()-H.ovr:0);
  let r=v13Rand(m);
  if(edge>5&&r<.30)hg++;
  if(edge<-5&&r<.30)ag++;
  // Avoid ultra-dead rounds: each fixture has at least 2 goals in V13.
  while(hg+ag<2){if(v13Rand(m)<.52)hg++;else ag++;}
  const arr=[];
  for(let i=0;i<hg;i++)arr.push({side:'H',minute:4+Math.floor(v13Rand(m)*88)});
  for(let i=0;i<ag;i++)arr.push({side:'A',minute:4+Math.floor(v13Rand(m)*88)});
  arr.sort((a,b)=>a.minute-b.minute);
  // Prevent multiple scheduled goals from collapsing onto exactly the same minute too often.
  for(let i=1;i<arr.length;i++)if(arr[i].minute===arr[i-1].minute)arr[i].minute=Math.min(92,arr[i].minute+1);
  g.goalSchedule=arr;g.goalCursor=0;
}
function simulateGameMinuteV13(g,m){
  v13BuildSchedule(g,m);
  const isCor=g.home==='Corinthians'||g.away==='Corinthians';
  // Scheduled goals fire when their minute arrives.
  while(g.goalCursor<g.goalSchedule.length && g.goalSchedule[g.goalCursor].minute<=m.minute){
    const ev=g.goalSchedule[g.goalCursor++],club=ev.side==='H'?g.home:g.away;let sc;
    if(club==='Corinthians'){
      let scorerId;[scorerId,m.seed]=corinthiansScorer(m.seed);sc=S.players[scorerId].name;S.players[scorerId].goals++;addScorer(sc,'Corinthians');
    }else{[sc,m.seed]=scorerFor(club,m.seed);addScorer(sc,club)}
    if(ev.side==='H')g.hg++;else g.ag++;
    if(isCor){
      if(ev.side==='H'){m.stats.shotsH++;m.stats.onH++}else{m.stats.shotsA++;m.stats.onA++}
      m.events.push({text:`⚽ ${m.display} • ${sc} marca para ${club}!`,special:true});
      ledger('goal',{club,scorer:sc,score:[g.hg,g.ag]});
      if(club==='Corinthians'){AudioFX.play('gol_corinthians');AudioFX.play('torcida_comemoracao',.85)}else AudioFX.play('gol_adversario');
    }else{
      g.events.push({minute:m.minute,scorer:sc,club});
      m.otherEvents=m.otherEvents||[];m.otherEvents.push({text:`⚽ ${m.display} • ${g.home} ${g.hg}–${g.ag} ${g.away} • ${sc}`});
    }
  }
  // Add non-goal match texture only for the Corinthians match.
  if(isCor){
    const r=v13Rand(m);
    if(r<.105){const corHome=g.home==='Corinthians',corChance=v13Rand(m)<.52;if(corChance){corHome?m.stats.shotsH++:m.stats.shotsA++}else{corHome?m.stats.shotsA++:m.stats.shotsH++}m.events.push({text:`${m.display} • ${corChance?'Corinthians':'Adversário'} cria uma boa chance, mas não marca.`});}
    else if(r<.118)m.events.push({text:`🟨 ${m.display} • Cartão amarelo.`});
  }
}
// Explicitly route every live fixture through V13; no dependency on duplicate legacy function names.
simulateAllMinute=function(){
  const m=S.match;Object.values(m.live).forEach(g=>simulateGameMinuteV13(g,m));
  const cg=Object.values(m.live).find(g=>g.home===m.home&&g.away===m.away);m.hg=cg.hg;m.ag=cg.ag;
};
// Build schedules immediately at kickoff so save/reload preserves the exact same goals/minutes.
const _v13Kickoff=kickoff;kickoff=function(){_v13Kickoff();if(S.match){Object.values(S.match.live).forEach(g=>v13BuildSchedule(g,S.match));S.version=13;save();}};
